EVENTS_PART2 = {
    # Volksraad events
    "INS_volksraad_events.2.t": "[HOL.GetLeader] telah memveto petisi Volksraad.",
    "INS_volksraad_events.2.desc": "Meskipun petisi tersebut telah disetujui oleh [INS.GetLeader], petisi itu diveto setelah ditinjau oleh [HOL.GetLeader], sehingga kita tidak dapat melanjutkan penerapannya saat ini.",
    "INS_volksraad_events.2.a": "Mungkin kita dapat mencoba lagi di masa depan dengan petisi yang diratifikasi.",
    "INS_volksraad_events.10.t": "Mosi di Volksraad untuk mengizinkan bahasa Indonesia di Sekolah",
    "INS_volksraad_events.10.desc": "[INS.GetLeader] telah menyetujui petisi Volksraad untuk mendorong pembukaan sekolah dan perguruan tinggi berbahasa Indonesia di [INS.GetNameDef], dan petisi tersebut telah dikirimkan kepada [HOL.GetLeader] untuk mendapatkan persetujuan akhir.",
    "INS_volksraad_events.10.a": "Volksraad menjalankan fungsinya sebagaimana mestinya.",
    "INS_volksraad_events.10.b": "Sama sekali tidak boleh. Veto petisi itu!",
    "INS_volksraad_events.11.t": "Pendidikan berbahasa Indonesia akan didirikan.",
    "INS_volksraad_events.11.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.11.a": "Volksraad menjalankan fungsinya sebagaimana mestinya.",
    "INS_volksraad_events.20.t": "Mosi di Volksraad untuk mengizinkan bahasa Indonesia di Pemerintahan",
    "INS_volksraad_events.20.desc": "Jabatan pemerintahan di Hindia, termasuk Volksraad, semuanya mewajibkan kefasihan berbahasa Belanda, yang membuat banyak anggota Volksraad, terutama perwakilan masyarakat pribumi, mempertanyakan keabsahan demokrasinya. Mereka telah menyusun mosi yang menegaskan bahwa jabatan pemerintahan harus dapat diisi oleh penutur bahasa Indonesia jika memungkinkan.",
    "INS_volksraad_events.21.t": "Bahasa Indonesia kini diizinkan di Pemerintahan!",
    "INS_volksraad_events.21.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.30.t": "Mosi di Volksraad untuk menghapuskan Sistem Kuota Pendidikan",
    "INS_volksraad_events.30.desc": "[INS.GetLeader] telah menyetujui petisi Volksraad untuk menghapuskan sistem kuota pendidikan di [INS.GetNameDef], guna mengakhiri perdebatan berkepanjangan di dalam Volksraad mengenai penerapan dan keadilannya. Petisi telah dikirimkan kepada [HOL.GetLeader] untuk persetujuan akhir.",
    "INS_volksraad_events.31.t": "Sistem Kuota Pendidikan telah dihapuskan.",
    "INS_volksraad_events.31.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.40.t": "Mosi di Volksraad untuk mengurangi pajak ekspor Karet",
    "INS_volksraad_events.40.desc": "[INS.GetLeader] telah menandatangani dan menyetujui petisi Volksraad untuk mengurangi pajak tinggi yang dibebankan pada perkebunan karet swasta. Pajak ini secara historis memungkinkan monopoli karet pemerintah yang sangat menguntungkan, namun proteksionisme internasional telah membuat sistem ini jauh kurang menguntungkan. [INS.GetLeader] menyatakan tidak lagi yakin bahwa pajak tersebut sepadan dengan dampak ekonomi yang ditimbulkannya.",
    "INS_volksraad_events.40.a": "[INS.GetLeader] ada benarnya.",
    "INS_volksraad_events.40.b": "Pajak tersebut harus tetap berlaku.",
    "INS_volksraad_events.41.t": "Pajak swasta atas Ekspor Karet telah dikurangi.",
    "INS_volksraad_events.41.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.60.t": "Mosi di Volksraad untuk mencabut batas pangkat tak tertulis bagi perwira Indonesia",
    "INS_volksraad_events.60.desc": "[INS.GetLeader] telah menyetujui petisi Volksraad untuk mencabut aturan tak tertulis yang membatasi pangkat perwira KNIL non-Belanda, serta menaikkan pangkat perwira Indonesia yang dianggap berpangkat di bawah pencapaian mereka. Petisi telah dikirimkan kepada [HOL.GetLeader] untuk persetujuan akhir.",
    "INS_volksraad_events.61.t": "Batas tak kasat mata bagi Jenderal [INS.GetAdjective] dicabut.",
    "INS_volksraad_events.61.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.70.t": "Mosi di Volksraad untuk melegalkan pengibaran bendera dan simbol nasionalis di muka umum",
    "INS_volksraad_events.70.desc": "[INS.GetLeader] telah menyetujui petisi Volksraad untuk mencabut pembatasan pengibaran bendera dan simbol nasionalis di ruang publik di [INS.GetNameDef], sebagian besar demi meredam radikalisasi kaum muda nasionalis. [INS.GetLeader] menegaskan bahwa kita harus mengambil sikap defensif dalam masalah ini, bekerja sama dengan para pemimpin nasionalis damai sembari menumpas gerakan revolusioner, namun keputusan akhir tetap berada di tangan kita.",
    "INS_volksraad_events.71.t": "Bendera Merah Putih tidak lagi ilegal untuk dikibarkan!",
    "INS_volksraad_events.71.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",
    "INS_volksraad_events.100.t": "Mosi di Volksraad untuk mengizinkan subsidi pendidikan bagi penduduk non-Belanda",
    "INS_volksraad_events.100.desc": "[INS.GetLeader] telah menyetujui petisi Volksraad untuk mengizinkan penduduk non-Belanda di [INS.GetNameDef] mengajukan subsidi pendidikan. Petisi telah dikirimkan kepada [HOL.GetLeader] untuk persetujuan akhir.",
    "INS_volksraad_events.101.t": "Masyarakat [INS.GetAdjective] kini dapat mengajukan Subsidi Pendidikan",
    "INS_volksraad_events.101.desc": "Petisi tersebut telah ditandatangani oleh [HOL.GetLeader], dan kini secara resmi diwajibkan. Pelaksanaan petisi akan segera dimulai setelah rincian akhir diputuskan.",

    # Union events
    "INS_union_events.1.t": "[HOL.GetNameDefCap] Meminta Pemindahan Pemerintahan ke [1058.GetName]",
    "INS_union_events.1.desc": "Dengan jatuhnya tanah air, [HOL.GetNameDef] telah memberitahukan kepada kita bahwa pemerintahan dan keluarga kerajaan mereka akan pindah ke [1058.GetName]. Mereka menulis tentang kebutuhan mendesak, kesinambungan, dan perlunya menjaga Kerajaan tetap hidup di mana bendera masih berkibar.",
    "INS_union_events.1.a": "Perang akan berlanjut dari [1058.GetName].",
    "INS_union_events.1.b": "Berani-beraninya mereka! Ini hanyalah upaya menegakkan kembali dominasi kolonial!",
    "INS_union_events.2.t": "[INS.GetNameDefCap] Menerima Usulan Relokasi",
    "INS_union_events.2.desc": "[INS.GetNameDefCap] telah sepakat untuk menampung pemerintahan pengasingan kita di [1058.GetName]. Persiapan pemindahan tengah berjalan, dan kedua administrasi sedang mengoordinasikan penggabungan kantor dan personel. Bersama-sama, kita akan meneruskan perjuangan Kerajaan dari Timur.",
    "INS_union_events.2.a": "Front persatuan melawan musuh bersama kita.",
    "INS_union_events.3.t": "[INS.GetNameDefCap] Menolak Usulan Relokasi",
    "INS_union_events.3.desc": "[INS.GetNameDefCap] telah menolak mentah-mentah permintaan kita untuk pindah ke [1058.GetName]. [INS.GetLeader] menyatakan bahwa kita tidak berhak menuntut bantuan sebesar ini ketika sumber daya mereka sendiri sudah sangat terbatas.",
    "INS_union_events.3.a": "Tampaknya mereka telah lupa panji siapa yang masih mengikat kita.",
    "INS_union_events.4.t": "[HOL.GetNameDefCap] Memindahkan Angkatan Bersenjata ke [1058.GetName]",
    "INS_union_events.4.desc": "Kapal-kapal angkut pertama telah tiba dari tanah air. Kapal-kapal tersebut penuh sesak dengan perwira, prajurit, dan sisa-sisa persenjataan kita. Sebagaimana diperkirakan, beberapa konvoi gagal mencapai pelabuhan. Mereka yang selamat akan menjadi tulang punggung pasukan kita di [1058.GetName].",
    "INS_union_events.4.a": "Cukup untuk menjaga sang bendera tetap berkibar.",
    "INS_union_events.5.t": "[INS.GetNameDefCap] Mengusulkan Uni Belanda–Indonesia",
    "INS_union_events.5.desc": "Jelas bagi dunia bahwa perang sedang tidak berpihak kepada kita. Negara kita telah jatuh dan pangkalan operasi kita berpindah ke timur. Para menteri di [INS.GetName] telah mengirimkan usulan untuk membentuk negara uni bersama yang dipimpin oleh Ratu Wilhelmina demi menjamin kerja sama semaksimal mungkin. Meskipun tampaknya tidak ada pihak yang benar-benar puas dengan usulan ini, ini mungkin kunci keselamatan kita.",
    "INS_union_events.5.a": "Ini risiko yang harus kita ambil. Hidup sang Ratu!",
    "INS_union_events.5.b": "Kita tidak dapat menyetujui ini.",
    "INS_union_events.6.t": "[HOL.GetNameDefCap] Menerima Usulan Uni",
    "INS_union_events.6.desc": "Setelah perdebatan mendesak di dalam kabinet, [HOL.GetLeader] telah menyetujui usulan [INS.GetAdjective]. Dekret tersebut singkat dan tanpa upacara. Pemerintahan kita selanjutnya akan bertindak sebagai satu kesatuan di bawah Mahkota hingga perang berakhir.",
    "INS_union_events.6.a": "Kesepakatan bersejarah bagi kedua bangsa.",
    "INS_union_events.7.t": "[HOL.GetNameDefCap] Menolak Usulan Uni",
    "INS_union_events.7.desc": "Dewan di [HOL.GetNameDef] telah menolak usulan pembentukan uni bersama. Pesan mereka tegas: kerja sama akan berlanjut, namun kedaulatan tidak akan dibagi.",
    "INS_union_events.7.a": "Lagi pula kecil kemungkinan hal ini akan berhasil.",
    "INS_union_events.8.t": "[HOL.GetNameDefCap] Mengusulkan Uni Belanda–Indonesia",
    "INS_union_events.8.desc": "Jelas bagi dunia bahwa perang tidak berpihak kepada kita. [HOL.GetNameDef] telah jatuh dan pangkalan operasi mereka berpindah ke timur. Para pemimpin [HOL.GetAdjective] telah mengirimi kita usulan pembentukan negara uni bersama yang dipimpin oleh Ratu Wilhelmina guna menjamin kerja sama yang erat. Meski tampaknya tak seorang pun sepenuhnya puas, ini mungkin jalan keselamatan kita.",
    "INS_union_events.8.a": "Ini harus dilakukan.",
    "INS_union_events.8.b": "Ini tak lain hanyalah upaya menegakkan kembali dominasi kolonial.",
    "INS_union_events.9.t": "[INS.GetNameDefCap] Menerima Usulan Uni",
    "INS_union_events.9.desc": "[INS.GetNameDefCap] telah menyetujui usulan kita. Belum jelas bagaimana ini akan berjalan, namun kita harus memusatkan perhatian pada upaya perang.",
    "INS_union_events.9.a": "Jika kita ingin bertahan, kita harus bertahan bersama-sama.",
    "INS_union_events.10.t": "[INS.GetNameDefCap] Menolak Usulan Uni",
    "INS_union_events.10.desc": "[INS.GetNameDefCap] telah menolak usulan uni. Rakyat dan para pemimpin [INS.GetAdjective] tidak melihat masa depan jangka panjang dalam skema ini, dan menentang segala usulan pelepasan kekuasaan.",
    "INS_union_events.10.a": "Lagi pula kecil kemungkinan hal ini akan berhasil.",

    # Communist events
    "INS_communist_events.6.t": "Agen [FROM.GetAdjective] Melakukan Agitasi di [ROOT.GetName]",
    "INS_communist_events.6.desc": "Dinas intelijen kita telah mengonfirmasi kecurigaan yang telah lama ada. [FROM.GetNameDefCap] telah melancarkan kampanye subversi berkesinambungan di dalam perbatasan kita, mendanai sel-sel radikal, menyebarkan pamflet hasutan, dan mengorganisasi pemogokan di kalangan buruh. Agen-agen mereka telah menyusup ke dalam serikat buruh dan koperasi tani, serta kini secara terbuka menyerukan penggulingan pemerintahan kita. Keadaan telah mencapai titik genting, dan kita harus bertindak tegas sebelum situasi lepas kendali.",
    "INS_communist_events.6.a": "Hal ini tidak boleh dibiarkan!",
    "INS_communist_events.7.t": "Subversi Komunis di [FROM.GetName]",
    "INS_communist_events.7.desc": "Laporan yang mencemaskan telah sampai kepada kita dari [FROM.FROM.GetName]. Agen-agen yang beroperasi atas nama [FROM.GetNameDef] telah mengobarkan sentimen revolusioner di kalangan penduduk setempat, memanfaatkan ketidakpuasan terhadap administrasi kita untuk menghimpun dukungan bagi perebutan kekuasaan komunis. Jika dibiarkan tanpa tindakan, [FROM.FROM.GetNameDef] dapat jatuh sepenuhnya ke tangan kaum radikal, dan pembusukan ini bisa merambat ke wilayah kekuasaan kita lainnya.",
    "INS_communist_events.7.a": "Kita harus memadamkan ini sebelum meluas!",
    "INS_communist_events.8.t": "Propaganda [FROM.GetAdjective] Beredar di [ROOT.GetName]",
    "INS_communist_events.8.desc": "Pamflet dan selebaran yang berasal dari [FROM.GetAdjective] kian marak bermunculan di pabrik-pabrik, pasar, dan universitas kita. Selebaran tersebut mendengungkan perang kelas dan menjanjikan pembebasan lewat revolusi, dan kepolisian melaporkan bahwa selebaran itu mendapat sambutan hangat dari kalangan yang kecewa. Materinya sederhana namun sangat memikat, dan penyebarannya tak menunjukkan tanda-tanda mereda.",
    "INS_communist_events.8.a": "Cari tahu siapa dalang penyebar materi busuk ini!",
    "INS_communist_events.1.t": "Revolusi di [ROOT.GetName]",
    "INS_communist_events.1.desc": "Situasi telah memburuk di luar kendali. Agitasi [FROM.GetAdjective] selama berbulan-bulan telah membuahkan hasil, dan gerakan komunis di [ROOT.GetName] tak dapat lagi dibendung dengan tindakan biasa. Pemogokan umum telah melumpuhkan kota-kota besar, partisan bersenjata menguasai seluruh provinsi, dan pemerintah [FROM.GetAdjective] telah mengerahkan segenap dukungannya di belakang kaum revolusioner. Pasukan keamanan kita kewalahan dan kesetiaan mereka tak lagi pasti. Kita harus memutuskan sekarang apakah akan berjuang demi kelangsungan negara atau menerima kenyataan sebelum darah tertumpah lebih banyak.",
    "INS_communist_events.1.a": "Kerahkan tentara. Kita tidak akan menyerah begitu saja.",
    "INS_communist_events.1.b": "Perlawanan lanjutan hanya akan membawa malapetaka bagi rakyat kita.",
    "INS_communist_events.1.c": "Mungkin jika kita memberi mereka tempat di pemerintahan, kita masih bisa mengendalikannya.",
    "INS_communist_events.2.t": "[FROM.GetNameDefCap] Memilih Bertempur",
    "INS_communist_events.2.desc": "Pemerintah di [FROM.GetName] menolak untuk tunduk, dan telah memerintahkan angkatan bersenjatanya untuk menumpas gerakan revolusioner dengan kekerasan. Kawan-kawan kita di sana telah bersiap di posisi masing-masing dan merebut kubu-kubu pertahanan kunci. Perjuangan ini tidak akan berlangsung singkat, namun rakyat [FROM.GetName] telah menjatuhkan pilihan mereka, dan kita akan memastikan mereka tidak berjuang sendirian.",
    "INS_communist_events.2.a": "Revolusi melangkah maju.",
    "INS_communist_events.3.t": "[FROM.GetNameDefCap] Telah Tumbang",
    "INS_communist_events.3.desc": "Pemerintahan lama di [FROM.GetName] telah bertekuk lutut. Menghadapi gelombang pasang gerakan revolusioner dan kepastian bahwa [ROOT.GetNameDef] berdiri tegak di belakangnya, mereka melihat tidak ada jalan lain selain menyerah. Kekuasaan telah diserahkan kepada partai komunis setempat, dan pemerintahan baru telah mulai menghubungi kita untuk meminta arahan. Satu lagi bangsa terbebas dari cengkeraman tatanan lama.",
    "INS_communist_events.3.a": "Kemenangan gemilang bagi rakyat pekerja sedunia.",
    "INS_communist_events.4.t": "Perang Saudara Meletus di [FROM.GetName]",
    "INS_communist_events.4.desc": "Kaum revolusioner komunis, bersenjata dan terorganisasi dengan dukungan dari [FROM.FROM.GetNameDef], telah melancarkan pemberontakan terbuka di [FROM.GetName]. Administrasi kolonial telah kehilangan kendali atas sebagian besar wilayah, dan sang gubernur melaporkan bahwa garnisun setempat tidak mampu memulihkan ketertiban tanpa bala bantuan.",
    "INS_communist_events.4.a": "Kirim pasukan tempur. [FROM.GetName] adalah milik kita!",
    "INS_communist_events.5.t": "[FROM.GetName] Jatuh ke Tangan Komunis",
    "INS_communist_events.5.desc": "Administrasi di [FROM.GetName] telah menyerah kepada para pemberontak komunis tanpa perlawanan berarti. Gubernur dan stafnya telah ditahan, bendera kita diturunkan, dan sebuah pemerintahan revolusioner diproklamasikan menggantikannya. Semua ini didalangi oleh [FROM.FROM.GetNameDef] dan agen-agen mereka, yang telah berbulan-bulan merongrong wibawa kita di sana. Ini tak lain adalah perampasan terang-terangan, dan tidak akan dibiarkan begitu saja.",
    "INS_communist_events.5.a": "Ini penghinaan yang keterlaluan!",
    "INS_communist_events.9.t": "Perwira [FROM.GetAdjective] Terlihat Bertemu dengan Kaum Pembangkang",
    "INS_communist_events.9.desc": "Operatif [FROM.GetAdjective] terpantau berkumpul bersama para penggerak demonstrasi dan pimpinan milisi di seantero negeri. Aktivis mahasiswa yang biasanya membagikan selebaran di sudut jalan kini menggelar rapat rahasia di balik pintu tertutup bersama orang-orang berpasporkan diplomatik [FROM.GetAdjective]. Penerbitan terlarang dicetak lebih cepat daripada kemampuan polisi menyitanya, dan unjuk rasa yang biasanya buyar dalam satu siang kini melumpuhkan seisi distrik berhari-hari. Komunis-komunis ini kian mahir berorganisasi dalam kelompok besar; jika kita tidak bertindak cepat, kita akan kehilangan kendali.",
    "INS_communist_events.9.a": "Tumpas agen-agen asing ini sekarang juga!",
    "INS_communist_events.10.t": "Retorika [FROM.GetAdjective] Makin Mendapat Tempat",
    "INS_communist_events.10.desc": "Pamflet-pamflet [FROM.GetAdjective] telah menyusup ke barak-barak militer dan kalangan pegawai negeri sipil, dan upaya penyitaan tak banyak membendung arusnya. Selebaran itu berkisah tentang bangsa-bangsa yang merdeka dari belenggu penindasan, tentang rakyat yang mencampakkan gubernur kolonial dan membangun kedaulatan mandiri. Seruan itu akan lebih mudah ditumpas seandainya kata-katanya tidak menggemakan kebenaran. Bahkan pejabat yang setia pun mulai bertanya-tanya secara bisik-bisik, apakah tatanan kita saat ini melayani rakyat kita sendiri atau sekadar memanjakan tuan penjajah kita.",
    "INS_communist_events.10.a": "Kita harus melangkah dengan sangat hati-hati.",

    # Limited War events (Malaya / Borneo)
    "INS_limited_war_events.1.t": "Hancurkan Malaya!",
    "INS_limited_war_events.1.desc": "Garis pertahanan musuh telah jebol dan prajurit kita merangsek maju tanpa rintangan. Di seberang Selat Malaka, negara boneka Inggris runtuh di bawah amarah rakyat. Boneka-boneka London itu mengira bayonet mereka mampu membendung roda sejarah. Mereka keliru besar.",
    "INS_limited_war_events.1.a": "Merdeka!",
    "INS_limited_war_events.1.b": "Hari yang gilang-gemilang bagi Republik.",
    "INS_limited_war_events.2.t": "Serangan Balik [FROM.GetAdjective]",
    "INS_limited_war_events.2.desc": "Apa yang semula dijanjikan sebagai serangan kilat terhadap rezim boneka kini berbalik menjadi kepahitan. Pasukan [FROM.GetAdjective], yang diperkuat oleh tuan imperialis mereka, telah mendesak prajurit kita dari tanah sengketa dan kini bercokol di sana sebagai penjajah. Setiap hari warta radio menyiarkan kecongkakan mereka. Terus menyerang mengundang kehinaan lebih lanjut, namun mundur berarti mengakui kekalahan di hadapan segenap nusantara.",
    "INS_limited_war_events.2.a": "Tarik mundur pasukan. Selamatkan apa yang masih bisa diselamatkan.",
    "INS_limited_war_events.2.b": "Kita tidak akan tunduk pada kaum boneka!",
    "INS_limited_war_events.3.t": "[FROM.GetName] Tunduk kepada Republik",
    "INS_limited_war_events.3.desc": "Kabar datang dari Kuala Lumpur. Pemerintah boneka, yang ditinggalkan pada saat-saat menentukan oleh para tuannya di London, telah menerima syarat-syarat kita daripada menyaksikan kota-kota mereka terbakar. Wilayah sengketa kini menjadi milik kita. Pelajaran berharga ini tidak akan luput dari perhatian negara-negara boneka lainnya di kawasan ini.",
    "INS_limited_war_events.3.a": "Indonesia bangkit perkasa.",
    "INS_limited_war_events.4.t": "[FROM.GetName] Menolak Syarat Kita",
    "INS_limited_war_events.4.desc": "[FROM.GetName] telah melemparkan tawaran kita kembali ke muka kita. Para menteri boneka, yang membaca naskah titipan dari Whitehall, menyatakan bahwa sejengkal tanah pun tidak akan diserahkan dan Republik itu sendiri harus ditundukkan sebelum moncong senjata terdiam.",
    "INS_limited_war_events.4.a": "Kalau begitu, biarkan meriam yang berbicara.",
    "INS_limited_war_events.5.t": "[FROM.GetNameDef] Menyerukan Penghancuran Kita",
    "INS_limited_war_events.5.desc": "[FROM.GetNameDefCap] telah mencampakkan dalih perang terukur yang tersisa. Siaran radio mereka kini terang-terangan berbicara tentang memutilasi Republik dan membagi-bagikan pulau-pulaunya kepada para penjajah lama. Tak akan ada akhir yang tenang dalam kemelut ini. Antara Indonesia tetap tegak berdiri pada akhirnya, atau tidak sama sekali.",
    "INS_limited_war_events.5.a": "Kita tegak atau gugur bersama.",
    "INS_limited_war_events.6.t": "Merangseknya Pasukan [FROM.GetAdjective] Tertahan",
    "INS_limited_war_events.6.desc": "Serangan mendadak [FROM.GetAdjective] sempat mengejutkan kita dan sejenak kita mengkhawatirkan hal terburuk. Namun laju serangan mereka kini terbenam dalam lumpur. Prajurit mereka kelelahan, garis logistik mereka terlalu panjang, dan gertakan dari London kian melempem di setiap pernyataan resmi. Republik dapat menunjukkan kemurahan hati dengan menawarkan jalan keluar bagi para boneka itu, kendati banyak kalangan menilai kemenangan mutlak lebih mengabdi pada cita-cita perjuangan.",
    "INS_limited_war_events.6.a": "Tawarkan mereka syarat perdamaian.",
    "INS_limited_war_events.6.b": "Tiada ampun bagi kaum boneka.",
    "INS_limited_war_events.7.t": "Serangan Kita Terhenti Total",
    "INS_limited_war_events.7.desc": "Serangan kita telah macet, dan celakanya musuh menyadari hal itu. Sebuah tuntutan datang dari seberang Selat. Letakkan senjata sekarang dan terima syarat mereka, atau saksikan daftar korban gugur membengkak demi hasil akhir yang sama. Pilihan yang mereka sodorkan hanyalah seberapa megah upacara pemakaman kita nanti.",
    "INS_limited_war_events.7.a": "Lebih baik damai yang pahit daripada perang yang menghancurkan.",
    "INS_limited_war_events.7.b": "Republik tidak pernah kenal kata menyerah.",
    "INS_limited_war_events.8.t": "[FROM.GetName] Menolak Bertekuk Lutut",
    "INS_limited_war_events.8.desc": "[FROM.GetName] membalas tawaran kita dengan pembangkangan terbuka. Para menterinya berkoar bahwa mereka lebih rela melihat setiap kampung dari Penang hingga Johor dibakar habis daripada memberikan satu konsesi pun kepada Republik. Peperangan pun berlanjut.",
    "INS_limited_war_events.8.a": "Jika demikian, terjadilah.",
    "INS_limited_war_events.9.t": "[FROM.GetName] Berniat Menghancurkan Republik!",
    "INS_limited_war_events.9.desc": "Penyadapan radio dari markas komando musuh mengonfirmasi ketakutan terburuk. Tak akan ada perundingan damai terukur, tak ada pengembalian batas garis yang kita pertahankan sebelumnya. Para boneka dan tuan mereka di London menuntut penyerahan tanpa syarat dari Republik, agar Indonesia dihancurkan berkeping-keping dan kepulauannya dikembalikan ke bawah telapak kaki sepatu lars imperialis. Terhadap ini hanya ada satu jawaban.",
    "INS_limited_war_events.9.a": "Indonesia tetap berdiri tegak!",

    # Martial Law events
    "INS_martial_law_events.1.t": "[INS.GetNameDefCap] ingin mempererat hubungan dagang dengan kita",
    "INS_martial_law_events.1.desc": "Presiden [INS.GetName] telah menghubungi kita untuk menyampaikan harapan memperkokoh hubungan dagang, serta agar [INS.GetName] memegang peranan lebih besar dalam Lingkungan Kemakmuran Bersama. Presiden [INS.GetName], [INS.GetLeader], menawarkan kesepakatan menggiurkan di mana karet dan komoditas lainnya akan dijual kepada kita bebas bea dan pajak, dengan pengendalian pasar guna memastikan harga tetap murah.",
    "INS_martial_law_events.1.a": "Tentu saja!",
    "INS_martial_law_events.1.b": "Kita tidak tertarik.",
    "INS_martial_law_events.2.t": "[FROM.GetName] menyetujui perjanjian dagang",
    "INS_martial_law_events.2.desc": "[ROOT.GetLeader] telah kembali dari pertemuannya dengan pemerintah [JAP.GetAdjective] di [JAP.GetCapitalVictoryPointName] hari ini membawa kabar gembira; Perjanjian dagang yang diusulkan di [JAP.GetCapitalVictoryPointName] telah disepakati oleh semua pihak dan akan segera diberlakukan.",
    "INS_martial_law_events.2.a": "Ini akan sangat menguntungkan perekonomian kedua negara!",
    "INS_martial_law_events.3.t": "[FROM.GetName] menolak perjanjian dagang",
    "INS_martial_law_events.3.desc": "[ROOT.GetLeader] telah kembali dari pertemuannya dengan pemerintah [JAP.GetAdjective] di [JAP.GetCapitalVictoryPointName] hari ini membawa kabar buruk bahwa perundingan menemui jalan buntu setelah kedua belah pihak menolak mengalah dalam pokok pembicaraan tertentu, sehingga tiada perjanjian dagang yang disahkan.",
    "INS_martial_law_events.3.a": "Sungguh disayangkan.",
    "INS_martial_law_events.4.t": "[FROM.GetName] meminta kita mengakui klaim Melayu mereka",
    "INS_martial_law_events.4.desc": "Seorang utusan dari [FROM.GetNameDef] telah menyampaikan permohonan resmi kepada pemerintah kita. Presiden [FROM.GetLeader], yang telah memproklamasikan penyatuan dunia Melayu sebagai sasaran utama pemerintahannya, meminta agar kita mengakui klaim [INS.GetAdjective] atas seluruh tanah beretnis Melayu, membentang dari Sri Lanka hingga Filipina.",
    "INS_martial_law_events.4.a": "Kita akan mengakui hak mereka atas tanah historis mereka.",
    "INS_martial_law_events.4.b": "Ini bukan urusan kita.",
    "INS_martial_law_events.5.t": "[FROM.GetName] mengakui klaim kita",
    "INS_martial_law_events.5.desc": "Pemerintah [FROM.GetName] secara resmi telah mengakui klaim kita atas tanah-tanah Melayu. Dengan restu dari sekutu kita yang paling digdaya, penyatuan dunia Melayu kini tampak jauh lebih nyata untuk diwujudkan.",
    "INS_martial_law_events.5.a": "Bersatu!",
    "INS_martial_law_events.6.t": "[FROM.GetName] menolak mengakui klaim kita",
    "INS_martial_law_events.6.desc": "Pemerintah [FROM.GetName] menolak mengakui klaim kita atas dunia Melayu. Tampaknya mereka yang mengaku sekutu kita lebih suka membiarkan bangsa-bangsa serumpun Melayu terpecah belah daripada melihat kita tumbuh kuat. Kita akan mengingat penghinaan ini saat waktunya tiba.",
    "INS_martial_law_events.6.a": "Ini hanyalah batu sandungan kecil; kita akan bertahan, kita akan menang!",
    "INS_martial_law_events.7.t": "[FROM.GetName] menuntut kendali atas Melayu Utara",
    "INS_martial_law_events.7.desc": "[FROM.GetName] telah mengirimkan permohonan resmi agar kita menepati pengakuan atas klaim Melayu mereka dengan mengatur penyerahan wilayah Melayu Utara kepada [FROM.GetName], yang saat ini dikuasai oleh [SIA.GetName]. Langkah ini mungkin akan membuat gusar kepemimpinan [SIA.GetAdjective], namun akan sangat memperkokoh ikatan persahabatan kita dengan [INS.GetName].",
    "INS_martial_law_events.7.a": "Kita harus menghormati perjanjian.",
    "INS_martial_law_events.7.b": "Tidak sepadan menciptakan perselisihan di dalam faksi.",
    "INS_martial_law_events.8.t": "[FROM.GetName] menolak permohonan kita",
    "INS_martial_law_events.8.desc": "Kendati mereka sebelumnya mengakui klaim kita secara resmi, pemerintah [JAP.GetAdjective] menolak memediasi penyerahan Melayu Utara, dengan [JAP.GetLeader] berkeras bahwa mereka tidak dapat menanggung risiko perpecahan di dalam faksi. Nyata sudah bahwa janji mereka hampa dan kata-kata mereka tiada artinya di hadapan keadaan genting.",
    "INS_martial_law_events.8.a": "Mereka menunjukkan ketidakmampuan untuk menepati komitmen.",
    "INS_martial_law_events.9.t": "[FROM.GetName] meminta kita menyerahkan Melayu Utara kepada [INS.GetNameDef]",
    "INS_martial_law_events.9.desc": "[FROM.GetName] telah memberitahu kita bahwa [INS.GetName] menuntut agar kita menyerahkan Melayu Utara kepada [INS.GetName] sebagai bagian dari klaim mereka atas seluruh tanah bangsa Melayu. Pemerintah [JAP.GetAdjective] secara resmi mendukung klaim [INS.GetAdjective], dan penasihat militer [JAP.GetAdjective] memperingatkan kita bisa menghadapi konflik bersenjata jika menolak.",
    "INS_martial_law_events.9.a": "Bukan berarti kita punya pilihan lain.",
    "INS_martial_law_events.9.b": "Kita tidak akan tunduk pada imperialisme!",
    "INS_martial_law_events.9.a.tt": "§W§RKita berisiko dipandang lemah, yang dapat memicu tuntutan konsesi baru di masa depan.§!§!",
    "INS_martial_law_events.10.t": "[JAP.GetName] dan [FROM.GetName] menyetujui penyerahan",
    "INS_martial_law_events.10.desc": "[JAP.GetName] telah sepakat memediasi penyerahan Melayu Utara, dan telah mengirimkan utusan untuk berunding di [SIA.GetCapitalVictoryPointName], bersama para utusan [INS.GetAdjective]. Kesepakatan telah dicapai oleh ketiga pihak, menetapkan bahwa Melayu Utara, berlaku segera, resmi menjadi wilayah [INS.GetAdjective].",
    "INS_martial_law_events.10.a": "Luar biasa!",
    "INS_martial_law_events.11.t": "[FROM.GetName] menolak penyerahan",
    "INS_martial_law_events.11.desc": "[SIA.GetLeader] menolak menghadiri perundingan, menegaskan bahwa ia tidak berniat menyerahkan Melayu Utara apa pun konsekuensinya. Ketika kami mengingatkan beratnya konsekuensi keputusan ini, [SIA.GetLeader] bergeming dan mengabaikan gertakan kita, menolak tunduk pada tuntutan apa pun. Hal ini menyisakan sedikit pilihan bagi kita.",
    "INS_martial_law_events.11.a": "Kalau begitu, terjadilah perang.",
    "INS_martial_law_events.12.t": "[FROM.GetName] memberitahu bahwa [SIA.GetName] menolak tunduk",
    "INS_martial_law_events.12.desc": "Utusan dari [FROM.GetName] telah tiba di [ROOT.GetCapitalVictoryPointName] membawa kabar buruk bahwa pihak [SIA.GetAdjective] menolak mentah-mentah segala penyerahan maupun perundingan, dan [JAP.GetNameDef] telah secara resmi mendepak [SIA.GetNameDef] keluar dari faksi.",
    "INS_martial_law_events.12.a": "Kalau begitu, perang jalan keluarnya.",
    "INS_martial_law_events.13.t": "[FROM.GetName] meminta pertuanan atas [SIA.GetName]",
    "INS_martial_law_events.13.desc": "[FROM.GetName] telah menyampaikan keinginan mereka untuk memegang pertuanan atas [SIA.GetName], menyusul pandangan [FROM.GetLeader] bahwa [SIA.GetName] adalah bangsa lemah yang tak mampu membela dirinya sendiri, yang terbukti gamblang dari ketundukan kilat mereka atas urusan Melayu Utara. Jasa besar yang diberikan [INS.GetName] bagi faksi sangatlah nyata, dan tampaknya kita berisiko kehilangan mereka sebagai sekutu jika kita mengabaikan permintaan ini.",
    "INS_martial_law_events.13.a": "Mereka pantas mendapatkannya.",
    "INS_martial_law_events.13.b": "Sama sekali tidak.",
    "INS_martial_law_events.14.t": "[FROM.GetName] menyetujui penyerahan",
    "INS_martial_law_events.14.desc": "Pemerintah [FROM.GetName] telah sepakat untuk menempatkan [SIA.GetNameDef] di bawah wewenang kita, berlaku segera.",
    "INS_martial_law_events.14.a": "Bagus sekali.",
    "INS_martial_law_events.15.t": "[FROM.GetName] menolak penyerahan",
    "INS_martial_law_events.15.desc": "Pemerintah [FROM.GetName] menolak menyerahkan pertuanan atas [SIA.GetName] kepada kita, kendati ketidakmampuan mereka membela diri telah terbukti nyata.",
    "INS_martial_law_events.15.a": "Sayang sekali.",
    "INS_martial_law_events.16.t": "Kepemimpinan Baru untuk [ROOT.GetName]",
    "INS_martial_law_events.16.desc": "Dengan restrukturisasi pemerintahan kita menjadi Persatuan Provinsi-Provinsi Indonesia, sistem presidensial terdahulu yang mengawasi dewan terpilih demokratis akan digantikan dengan sistem presidensial federal yang baru. Kita harus memilih Presiden baru.",
    "INS_martial_law_events.16.a": "Ini hanyalah penataan ulang internal, pertahankan kepemimpinan yang ada.",
    "INS_martial_law_events.16.b": "Hatta yang akan mengambil alih tampuk kepemimpinan.",
    "INS_martial_law_events.16.c": "Kartosoewirjo adalah pilihan yang sangat populer!",
    "INS_martial_law_events.16.d": "Pemerintahan militer yang dibutuhkan untuk saat ini.",
}
